          dr = -1; dc = 0;
        } else if (stick.y > 0.5) {
          dr = 1; dc = 1;
        } else if (stick.x < -0.5) {
          dr = -1; dc = -1;
        } else if (stick.x > 0.5) {
          dr = 1; dc = 1;
        }
